public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        String s = r.next();
        long x = r.nextLong(), y = r.nextLong();
        final long INF = Long.MAX_VALUE / 4;
        long c0 = INF, c1 = INF;
        if (s.charAt(0) != '1') c0 = 0;
        if (s.charAt(0) != '0') c1 = 0;
        for (int i = 1; i < s.length(); i++) {
            char ch = s.charAt(i);
            // only the new adjacent pair (previous bit, current bit) adds cost
            long n0 = ch == '1' ? INF : Math.min(c0, c1 + y);
            long n1 = ch == '0' ? INF : Math.min(c1, c0 + x);
            c0 = n0;
            c1 = n1;
        }
        System.out.println(Math.min(c0, c1));
    }
}


final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

